(function() {
    // আগের স্ক্রিপ্ট সাফ করা
    ['nova-xray', 'nova-toast', 'nova-god-style'].forEach(id => {
        let el = document.getElementById(id);
        if(el) el.remove();
    });

    console.log("🖐️ Axiom X-Ray Bot 13.0 (Anti-Select Telekinesis) Injected!");

    // ১. স্টাইল শিট (Anti-Select পাওয়ার যুক্ত করা হয়েছে)
    const style = document.createElement('style');
    style.id = 'nova-god-style';
    style.textContent = `
        #nova-xray { position: fixed; top: 30px; left: 10px; z-index: 2147483647; display: flex; flex-direction: column; gap: 8px; background: rgba(0,0,0,0.7); padding: 8px; border-radius: 30px; cursor: move; touch-action: none; box-shadow: 0 4px 15px rgba(0,0,0,0.5); backdrop-filter: blur(5px); border: 1px solid #555; }
        .nx-btn { background: #000; color: #fff; border: 2px solid #333; border-radius: 50%; width: 40px; height: 40px; font-size: 18px; display: flex; align-items: center; justify-content: center; cursor: pointer; transition: 0.3s; outline: none; }
        .nx-btn.active { background: #ea4335; border-color: #ea4335; box-shadow: 0 0 12px rgba(234,67,53,0.8); }

        #nova-toast { position: fixed; bottom: -60px; left: 50%; transform: translateX(-50%); background: #202124; color: #fff; padding: 12px 24px; border-radius: 30px; z-index: 2147483647; font-family: sans-serif; font-size: 14px; font-weight: bold; transition: bottom 0.4s cubic-bezier(0.18, 0.89, 0.32, 1.28); pointer-events: none; border: 1px solid #34a853; box-shadow: 0 5px 15px rgba(0,0,0,0.5); white-space: nowrap; }
        #nova-toast.show { bottom: 50px; }

        /* 🖐️ গড মোড অন থাকলে হোভার ইফেক্ট এবং টেক্সট সিলেকশন পুরোপুরি বন্ধ করা */
        body.telekinesis-active * { 
            cursor: default; 
            -webkit-user-select: none !important; /* Safari/Chrome */
            -moz-user-select: none !important; /* Firefox */
            -ms-user-select: none !important; /* IE/Edge */
            user-select: none !important; /* Standard */
            -webkit-touch-callout: none !important; /* iOS/WebView long-press popup block */
        }
        body.telekinesis-active *:hover { outline: 1px dashed #aaa !important; outline-offset: -1px; }

        /* 🔓 লং প্রেস করার পর আনলক হওয়া এলিমেন্টের স্টাইল */
        .nova-unlocked { 
            box-shadow: 0 0 20px #34a853 !important; 
            outline: 3px solid #34a853 !important; 
            transform: scale(1.05) !important; 
            cursor: grabbing !important; 
            z-index: 2147483640 !important;
            transition: transform 0.2s, box-shadow 0.2s !important;
        }

        /* আমাদের মেনুকে এই জাদুর বাইরে রাখা */
        body.telekinesis-active #nova-xray, body.telekinesis-active #nova-xray * { outline: none !important; cursor: default !important; }
        body.telekinesis-active #nova-xray { cursor: move !important; }
    `;
    document.head.appendChild(style);

    // ২. মেনু তৈরি
    const menu = document.createElement('div'); menu.id = 'nova-xray';
    const btnEdit = document.createElement('button'); btnEdit.className = 'nx-btn'; btnEdit.innerText = '✍️';
    const btnGod = document.createElement('button'); btnGod.className = 'nx-btn'; btnGod.innerText = '🖐️';

    menu.appendChild(btnEdit); menu.appendChild(btnGod);
    document.body.appendChild(menu);

    // ৩. টোস্ট মেকানিজম
    const toast = document.createElement('div'); toast.id = 'nova-toast'; document.body.appendChild(toast);
    let toastTimer;
    function reportToast(msg) {
        toast.innerText = msg; toast.classList.add('show');
        clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('show'), 2500);
    }

    // ৪. মেনু ড্র্যাগ করার লজিক
    let isMenuDragging = false, mStartX, mStartY, mInitX, mInitY;
    function menuDragStart(e) {
        isMenuDragging = false; let evt = e.type.includes('touch') ? e.touches[0] : e;
        mStartX = evt.clientX; mStartY = evt.clientY; let rect = menu.getBoundingClientRect();
        mInitX = rect.left; mInitY = rect.top;
        document.addEventListener(e.type.includes('touch') ? 'touchmove' : 'mousemove', menuDragMove, {passive: false});
        document.addEventListener(e.type.includes('touch') ? 'touchend' : 'mouseup', menuDragEnd);
    }
    function menuDragMove(e) {
        let evt = e.type.includes('touch') ? e.touches[0] : e;
        let dx = evt.clientX - mStartX; let dy = evt.clientY - mStartY;
        if (Math.abs(dx) > 5 || Math.abs(dy) > 5) {
            isMenuDragging = true; e.preventDefault();
            menu.style.left = (mInitX + dx) + 'px'; menu.style.top = (mInitY + dy) + 'px';
            menu.style.right = 'auto'; menu.style.bottom = 'auto';
        }
    }
    function menuDragEnd() {
        document.removeEventListener('mousemove', menuDragMove); document.removeEventListener('mouseup', menuDragEnd);
        document.removeEventListener('touchmove', menuDragMove); document.removeEventListener('touchend', menuDragEnd);
    }
    menu.addEventListener('mousedown', menuDragStart); menu.addEventListener('touchstart', menuDragStart, {passive: false});

    // ✍️ Edit Mode
    btnEdit.onclick = () => {
        if (isMenuDragging) return;
        let isEditOn = document.designMode === 'on';
        document.designMode = isEditOn ? 'off' : 'on';
        btnEdit.classList.toggle('active', !isEditOn);
        reportToast(!isEditOn ? "✍️ Edit Mode On!" : "✍️ Edit Mode Off!");
    };

    // 🖐️ Long-Press Telekinesis Mode
    let isGodMode = false;
    let draggedElement = null;
    let longPressTimer = null;
    let isUnlocked = false;
    let dragStartX = 0, dragStartY = 0;
    let initialLeft = 0, initialTop = 0;
    let didElementMove = false;

    const godDragStart = (e) => {
        if (!isGodMode) return;
        let target = e.target;

        if (target.tagName === 'BODY' || target.tagName === 'HTML' || target.closest('#nova-xray') || target.closest('#nova-toast')) return;

        let evt = e.type.includes('touch') ? e.touches[0] : e;
        dragStartX = evt.clientX; dragStartY = evt.clientY;
        didElementMove = false;
        isUnlocked = false;

        // ⏱️ Long Press টাইমার (৫০০ মিলি-সেকেন্ড)
        longPressTimer = setTimeout(() => {
            isUnlocked = true;
            draggedElement = target;

            // এলিমেন্ট আনলক হওয়ার স্পেশাল ইফেক্ট
            draggedElement.classList.add('nova-unlocked');
            if (window.navigator.vibrate) window.navigator.vibrate(50); // মোবাইলে ছোট্ট ভাইব্রেশন

            let style = window.getComputedStyle(draggedElement);
            if (style.position === 'static') draggedElement.style.position = 'relative';

            let left = parseFloat(style.left); let top = parseFloat(style.top);
            initialLeft = isNaN(left) ? 0 : left; initialTop = isNaN(top) ? 0 : top;

        }, 500); // 500ms = আধা সেকেন্ড
    };

    const godDragMove = (e) => {
        if (!isGodMode) return;
        let evt = e.type.includes('touch') ? e.touches[0] : e;
        let dx = evt.clientX - dragStartX; let dy = evt.clientY - dragStartY;

        if (!isUnlocked) {
            // যদি আনলক হওয়ার আগেই ৫ পিক্সেলের বেশি নড়ে যায় (স্ক্রল করার সময়), তাহলে টাইমার বাতিল
            if (Math.abs(dx) > 5 || Math.abs(dy) > 5) clearTimeout(longPressTimer);
            return;
        }

        // আনলক হওয়ার পর ড্র্যাগ করা
        didElementMove = true;
        e.preventDefault(); 
        draggedElement.style.left = (initialLeft + dx) + 'px';
        draggedElement.style.top = (initialTop + dy) + 'px';
    };

    const godDragEnd = () => {
        clearTimeout(longPressTimer); // ক্লিক করে ছেড়ে দিলে টাইমার অফ
        if (draggedElement) {
            draggedElement.classList.remove('nova-unlocked'); // গ্লো ইফেক্ট মুছে ফেলা
            draggedElement = null;
        }
        isUnlocked = false;
    };

    const godPreventClick = (e) => {
        if (isGodMode && didElementMove) {
            e.preventDefault(); e.stopPropagation();
            didElementMove = false;
        }
    };

    // মোবাইলে লং প্রেস করার সময় যেন ব্রাউজারের রাইট-ক্লিক মেনু ওপেন না হয়
    const preventContextMenu = (e) => {
        if (isGodMode) {
            e.preventDefault();
        }
    };

    // 🖐️ বাটনের সুইচ লজিক
    btnGod.onclick = () => {
        if (isMenuDragging) return;
        isGodMode = !isGodMode;
        btnGod.classList.toggle('active', isGodMode);

        if (isGodMode) {
            document.body.classList.add('telekinesis-active');
            reportToast("🖐️ Hold any element for 0.5s to Unlock & Drag! (Text Selection Blocked)");

            document.addEventListener('mousedown', godDragStart);
            document.addEventListener('mousemove', godDragMove, {passive: false});
            document.addEventListener('mouseup', godDragEnd);

            document.addEventListener('touchstart', godDragStart, {passive: false});
            document.addEventListener('touchmove', godDragMove, {passive: false});
            document.addEventListener('touchend', godDragEnd);

            document.addEventListener('click', godPreventClick, true);
            document.addEventListener('contextmenu', preventContextMenu); // Context menu block
        } else {
            document.body.classList.remove('telekinesis-active');
            reportToast("🕊️ Telekinesis Off. Site is back to normal.");

            document.removeEventListener('mousedown', godDragStart);
            document.removeEventListener('mousemove', godDragMove);
            document.removeEventListener('mouseup', godDragEnd);

            document.removeEventListener('touchstart', godDragStart);
            document.removeEventListener('touchmove', godDragMove);
            document.removeEventListener('touchend', godDragEnd);

            document.removeEventListener('click', godPreventClick, true);
            document.removeEventListener('contextmenu', preventContextMenu);
        }
    };

})();
